function transfer(address recipient, uint256 amount) public returns (bool) {
    require(amount <= balanceOf[msg.sender]);
    balanceOf[msg.sender] -= amount;
    balanceOf[recipient] += amount;
    emit Transfer(msg.sender, recipient, amount);
    return true;
}

function transferFrom(address sender, address recipient, uint256 amount) public returns (bool) {
    require(amount <= balanceOf[sender]);
    balanceOf[sender] -= amount;
    balanceOf[recipient] += amount;
    emit Transfer(sender, recipient, amount);
    return true;
}

function mintToken(uint256 amount) public onlyOwner returns (bool) {
    require(amount > 0);
    totalSupply += amount;
    balanceOf[msg.sender] += amount;
    emit Transfer(address(0), msg.sender, amount);
    return true;
}

function buy(uint256 amount) public payable returns (bool) {
    require(msg.value >= amount * price);
    balanceOf[msg.sender] += amount;
    totalSupply += amount;
    emit Transfer(address(0), msg.sender, amount);
    return true;
}

function sell(uint256 amount) public returns (bool) {
    require(amount > 0);
    require(balanceOf[msg.sender] >= amount);
    balanceOf[msg.sender] -= amount;
    totalSupply -= amount;
    emit Transfer(msg.sender, address(0), amount);
    return true;
}
